// Individual video FX editor: draft-only changes, clip-relative keyframes and preview.
const effectEditor=document.createElement('dialog');effectEditor.id='effectEditor';effectEditor.className='work-dialog';effectEditor.style.width='min(1000px,94vw)';document.body.append(effectEditor);
const editorStyle=document.createElement('style');editorStyle.textContent='#effectEditor .fx-editor-columns{display:grid;grid-template-columns:minmax(240px,1fr) minmax(240px,1fr);gap:20px}#effectEditor canvas{width:100%;background:#050e20}#effectEditor .fx-preview{aspect-ratio:16/9;object-fit:contain}#effectEditor input[type=range]{width:100%;padding:0}#effectEditor .fx-curve{height:150px;touch-action:none;cursor:crosshair}#effectEditor .fx-editor-time{width:100%}#effectEditor #editorPoints{width:100%}@media(max-width:700px){#effectEditor .fx-editor-columns{grid-template-columns:1fr}}';document.head.append(editorStyle);
let effectEditorSession=null;
function openEffectEditor(clip,key){
  if(clip.dataset.kind!=='video'){openClipEffects(clip);return;}if(effectEditor.open||exporting||historyBusy||effectsBusy||!clip.isConnected)return;
  stopTimelinePlayback();const duration=clipTiming(clip).durationSeconds,draft=structuredClone({...LQTACEffects.videoDefaults,...clipEffectsState(clip,'video')});draft.enabled=true;draft.animation={...draft.animation};
  const groups={brightness:['brightness','contrast'],saturation:['saturation'],temperature:['temperature'],blur:['blur'],sharpen:['sharpen'],vignette:['vignette'],chroma:['chromaTolerance','chromaSoftness'],lut:[]};
  const names={brightness:'Brillo',contrast:'Contraste',saturation:'Saturación',temperature:'Temperatura',blur:'Desenfoque',sharpen:'Enfoque',vignette:'Viñeta',chromaTolerance:'Tolerancia de croma',chromaSoftness:'Suavidad de croma'};
  for(const [id,,fields] of LQTACEffects.creative){groups[id]=fields.map(p=>p[0]);for(const [p,label] of fields)names[p]=label;}
  const parameters=groups[key]||[key],title=effectsCatalog.video.find(p=>p[0]===key)?.[1]||key;
  effectEditor.innerHTML='<h2 id="editorTitle"></h2><div class="fx-editor-columns"><section><canvas id="editorPreview" class="fx-preview" width="640" height="360"></canvas><p id="editorClipName"></p><button id="editorPlay" type="button">▶ Reproducir clip</button><label><input id="editorBypass" type="checkbox"> Ver original sin efectos</label><p id="editorStatus" role="status"></p></section><section><div id="editorFields"></div><div id="editorAnimation"><label>Parámetro de la curva<select id="editorParameter"></select></label><label><input id="editorAnimate" type="checkbox"> Animar este parámetro</label><button id="editorAdd" type="button">Añadir / actualizar punto</button> <button id="editorRemove" type="button">Eliminar punto</button><p>Pulsa o arrastra en la curva para crear y mover puntos. La transición entre puntos es gradual y lineal.</p></div></section></div><label>Tiempo dentro del clip<input id="editorTime" class="fx-editor-time" type="range" min="0" step="0.001" value="0"></label><p id="editorTimeLabel"></p><canvas id="editorCurve" class="fx-curve" width="900" height="150"></canvas><select id="editorPoints" size="3" aria-label="Puntos de animación"></select><footer><button id="editorCancel" type="button">Cancelar</button><button id="editorSave" type="button">Aplicar al clip</button></footer>';
  $('#editorTitle').textContent=title;$('#editorClipName').textContent=clip.firstChild?.textContent||'Clip';$('#editorTime').max=String(duration);
  const fields=$('#editorFields');
  for(const p of parameters){const label=document.createElement('label');label.textContent=names[p]||p;const input=document.createElement('input');input.type='number';input.step='any';input.min=LQTACEffects.ranges.video[p][0];input.max=LQTACEffects.ranges.video[p][1];input.id='editor-'+p;label.append(input);fields.append(label);const option=document.createElement('option');option.value=p;option.textContent=names[p]||p;$('#editorParameter').append(option);}
  if(key==='chroma'){fields.insertAdjacentHTML('beforeend','<label><input id="editorChroma" type="checkbox"> Activar croma</label><label>Color a eliminar<input id="editorColor" type="color"></label>');$('#editorChroma').checked=draft.chroma;$('#editorColor').value=draft.chromaColor;}
  if(key==='lut'){fields.innerHTML='<label>Tabla LUT 3D<input type="file" id="editorLutFile" accept=".cube"></label><p id="editorLutName"></p><button type="button" id="editorLutRemove">Quitar LUT</button><p>La tabla LUT es fija en esta entrega; usa los demás efectos para animar ajustes.</p>';$('#editorLutName').textContent=draft.lut?.name||'Sin LUT';$('#editorAnimation').hidden=true;$('#editorCurve').hidden=true;$('#editorPoints').hidden=true;}
  const video=clip.dataset.generator?LQTACGenerators.media(clip):document.createElement('video');video.muted=true;video.playsInline=true;video.preload='auto';
  let pointTools=null;let time=0,playingPreview=false,frameId=0,closed=false,seeking=false,seekVersion=0;
  const session={clip,key,draft,video,get time(){return time;},setTime:value=>{time=Math.max(0,Math.min(duration,value));update();requestSeek();},render:()=>paint()};effectEditorSession=session;
  const parameter=()=>$('#editorParameter').value;
  const points=()=>draft.animation[parameter()]||[];
  function stop(){playingPreview=false;video.pause();cancelAnimationFrame(frameId);$('#editorPlay').textContent='▶ Reproducir clip';}
  function valueAtTime(p){return LQTACEffects.at(draft,time)[p];}
  function graph(){const canvas=$('#editorCurve'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,900,150);ctx.strokeStyle='#24456b';for(let i=0;i<=10;i++){ctx.beginPath();ctx.moveTo(i*90,0);ctx.lineTo(i*90,150);ctx.stroke();}const p=parameter();if(!p)return;const [min,max]=LQTACEffects.ranges.video[p],toY=value=>140-(value-min)/(max-min)*130,curve=points();ctx.strokeStyle='#75daff';ctx.lineWidth=2;ctx.beginPath();for(let x=0;x<=900;x+=3){const y=toY(LQTACEffects.valueAt(curve,x/900*duration,draft[p]));x?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();for(const point of curve){ctx.fillStyle=Math.abs(point.time-time)<.00101?'#ffcc70':'#eaf6ff';ctx.beginPath();ctx.arc(point.time/duration*900,toY(point.value),5,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#ffcc70';ctx.beginPath();ctx.moveTo(time/duration*900,0);ctx.lineTo(time/duration*900,150);ctx.stroke();}
  function update(){if(closed)return;$('#editorTime').value=String(time);$('#editorTimeLabel').textContent=`${time.toFixed(3)} s / ${duration.toFixed(3)} s · tiempo del clip`;for(const p of parameters)if(document.activeElement!==$('#editor-'+p))$('#editor-'+p).value=String(Number(valueAtTime(p).toFixed(4)));const p=parameter();$('#editorAnimate').checked=!!draft.animation[p];const list=$('#editorPoints');list.replaceChildren();for(const point of points()){const option=document.createElement('option');option.value=String(point.time);option.textContent=`${point.time.toFixed(3)} s · ${point.value.toFixed(4)}`;option.selected=Math.abs(point.time-time)<.001;list.append(option);}graph();paint();pointTools?.refresh();}
  function paint(){if(closed||video.readyState<2)return;try{const canvas=$('#editorPreview'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,640,360);const source=$('#editorBypass').checked?video:LQTACVideoEffects.draw(video,draft,time);LQTACWork.drawCrop(ctx,source,640,360,LQTACWork.cropAt(clipCropFrames(clip),time));}catch(error){$('#editorStatus').textContent=error.message;}}
  async function requestSeek(){if(closed)return;seekVersion++;if(seeking||video.readyState<1)return;seeking=true;try{let version;do{version=seekVersion;const target=Math.max(0,Math.min(video.duration-.001,clipPlaybackOffset(clip)+time*Number(clip.dataset.playbackRate||1)));if(Math.abs(video.currentTime-target)>.00001){video.currentTime=target;await waitMedia(video,()=>video.readyState>=2&&!video.seeking);}await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(closed)return;paint();}while(version!==seekVersion);}catch(error){if(!closed)$('#editorStatus').textContent=error.message;}finally{seeking=false;}}
  function setPoint(p,t,value){let curve=draft.animation[p]||[];curve=curve.filter(point=>Math.abs(point.time-t)>.001);if(curve.length>=998)throw Error('Máximo de puntos alcanzado');curve.push({time:t,value});curve.sort((a,b)=>a.time-b.time);draft.animation[p]=curve;}
  for(const p of parameters)$('#editor-'+p).oninput=event=>{const value=Number(event.target.value),[min,max]=LQTACEffects.ranges.video[p];if(!Number.isFinite(value)||value<min||value>max)return;if(draft.animation[p])setPoint(p,time,value);else draft[p]=value;update();};
  $('#editorTime').oninput=event=>{stop();time=Number(event.target.value);update();void requestSeek();};
  $('#editorParameter').onchange=update;
  $('#editorAnimate').onchange=event=>{const p=parameter();if(event.target.checked){const value=valueAtTime(p);draft.animation[p]=[{time:0,value},{time:duration,value}];}else{draft[p]=valueAtTime(p);delete draft.animation[p];}update();};
  $('#editorAdd').onclick=()=>{const p=parameter();if(!p)return;setPoint(p,time,valueAtTime(p));update();};
  $('#editorRemove').onclick=()=>{const p=parameter();if(!p)return;const remaining=points().filter(point=>Math.abs(point.time-time)>.001);if(remaining.length)draft.animation[p]=remaining;else delete draft.animation[p];update();};
  $('#editorPoints').onchange=event=>{stop();time=Number(event.target.value);update();void requestSeek();};
  $('#editorBypass').onchange=paint;
  $('#editorCurve').onpointerdown=event=>{
    if(event.button!==0||!parameter())return;event.preventDefault();stop();const canvas=event.currentTarget,rect=canvas.getBoundingClientRect(),p=parameter(),[min,max]=LQTACEffects.ranges.video[p];
    const coords=e=>({time:Math.max(0,Math.min(duration,(e.clientX-rect.left)/rect.width*duration)),value:Math.max(min,Math.min(max,min+(1-(e.clientY-rect.top-10*rect.height/150)/(130*rect.height/150))*(max-min)))});
    const hit=points().find(point=>Math.abs(point.time/duration*rect.width-(event.clientX-rect.left))<10&&Math.abs((140-(point.value-min)/(max-min)*130)/150*rect.height-(event.clientY-rect.top))<10);
    const node=hit||coords(event);if(!hit){setPoint(p,node.time,node.value);}let moving=points().find(point=>Math.abs(point.time-node.time)<.001);time=moving.time;update();void requestSeek();
    const move=e=>{const value=coords(e),curve=points(),index=curve.indexOf(moving),low=index>0?curve[index-1].time+.0001:0,high=index<curve.length-1?curve[index+1].time-.0001:duration;LQTACKeyframes.retime(curve,moving,value.time,duration);moving.value=value.value;time=moving.time;update();void requestSeek();};
    const finish=()=>{effectEditor.removeEventListener('close',finish);window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',finish);};effectEditor.addEventListener('close',finish,{once:true});window.addEventListener('pointermove',move);window.addEventListener('pointerup',finish);window.addEventListener('pointercancel',finish);
  };
  if(key==='chroma'){const change=()=>{draft.chroma=$('#editorChroma').checked;draft.chromaColor=$('#editorColor').value;paint();};$('#editorChroma').onchange=change;$('#editorColor').oninput=change;}
  if(key==='lut'){$('#editorLutRemove').onclick=()=>{draft.lut=null;$('#editorLutName').textContent='Sin LUT';paint();};$('#editorLutFile').onchange=async e=>{try{const file=e.target.files[0];if(file){if(file.size>16*1024*1024)throw Error('LUT demasiado grande');draft.lut=LQTACEffects.parseCube(await file.text(),file.name);$('#editorLutName').textContent=file.name;paint();}}catch(error){$('#editorStatus').textContent=error.message;}};}
  function tick(){if(!playingPreview||closed)return;time=Math.min(duration,Math.max(0,(video.currentTime-clipPlaybackOffset(clip))/Number(clip.dataset.playbackRate||1)));update();if(time>=duration-.001||video.ended)stop();else frameId=requestAnimationFrame(tick);}
  $('#editorPlay').onclick=async()=>{if(playingPreview){stop();return;}try{if(time>=duration-.001)time=0;await requestSeek();video.playbackRate=Number(clip.dataset.playbackRate||1);await video.play();playingPreview=true;$('#editorPlay').textContent='❚❚ Pausar clip';frameId=requestAnimationFrame(tick);}catch(error){$('#editorStatus').textContent=error.message;}};
  $('#editorCancel').onclick=()=>effectEditor.close();
  $('#editorSave').onclick=async()=>{try{if([...effectEditor.querySelectorAll('input[type=number]')].some(field=>!field.checkValidity()))throw Error('Revisa los valores del filtro');LQTACEffects.validate(draft,'video');if(!clip.isConnected)throw Error('El clip ya no existe');stop();historyCheckpoint();clip.dataset.videoFx=JSON.stringify(draft);effectEditor.close();await renderTimelineAt(timelineTime);toast('Efecto y animación aplicados al clip');}catch(error){$('#editorStatus').textContent=error.message;}};
  effectEditor.onclose=()=>{closed=true;stop();video.dispose?.();video.removeAttribute('src');video.load();if(effectEditorSession===session)effectEditorSession=null;};
  $('#editorStatus').textContent='Cargando vista previa del clip…';video.onloadeddata=()=>{if(!closed){$('#editorStatus').textContent='';update();void requestSeek();}};video.onerror=()=>{if(!closed)$('#editorStatus').textContent='No se pudo reproducir la fuente del clip';};
  if(parameters.length)pointTools=LQTACKeyframes.install({dialog:effectEditor,canvas:$('#editorCurve'),list:$('#editorPoints'),remove:$('#editorRemove'),duration,band:parameter,time:()=>time,entries:()=>points().map(point=>({point,band:parameter()})),position:({point,band},rect)=>{const [min,max]=LQTACEffects.ranges.video[band];return {x:point.time/duration*rect.width,y:(140-(point.value-min)/(max-min)*130)/150*rect.height};},select:({point,band})=>{$('#editorParameter').value=band;time=point.time;stop();update();void requestSeek();},erase:({point,band})=>{stop();const curve=draft.animation[band];curve.splice(curve.indexOf(point),1);if(!curve.length)delete draft.animation[band];update();},retime:({point,band},t)=>{stop();return LQTACKeyframes.retime(draft.animation[band],point,t,duration);}});
  effectEditor.showModal();update();if(clip.dataset.generator)void video.initialize();else void clipPlaybackPath(clip).then(mediaUrlForTimeline).then(url=>{if(!closed){video.src=url;video.load();}}).catch(error=>{$('#editorStatus').textContent=error.message;});
}
// Catalog cards open one effect, not the complete settings form.
$$('#effectsCatalog [data-fx-kind="video"]').forEach(button=>{button.onclick=()=>{const clip=effectsTarget('video');if(!clip){$('#effectsSelection').textContent='Selecciona un clip de vídeo en la timeline.';return;}openEffectEditor(clip,button.dataset.fxKey);};});
function openAudioEffectEditor(clip,key){return openAnimatedAudioEditor(clip,key);}
$$('#effectsCatalog [data-fx-kind="audio"]').forEach(button=>{button.onclick=()=>{const clip=effectsTarget('audio');if(!clip){$('#effectsSelection').textContent='Selecciona un clip de audio en la timeline.';return;}openAudioEffectEditor(clip,button.dataset.fxKey);};});
